INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7225183, 1113663, 142425, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by kiwinick:</b></div><hr/><i> good idea although I believe it is not a true macro rather a close up </i></td></tr></table> <br/> <br/>It rather depends on which definition of macro you go by, kiwinick: an image that is 1 to 1 (or larger) on recording media, or; an image that is 1 to 1 (or lager) on output media.<br/> <br/>With sensor sizes, and to a certain extent film sizes, varying so much it is hard to apply the first criteria with any form of consistent accuracy. Applying the second might be easier if the print output is used as a constant but with output media now meaning anything from a phone to a PC, this too is becoming hard to verify; though I believe my image conforms to it. Put the picture up on your screen or print it out and compare the size of an sd-card with the one in the image.<br/> <br/>Do not confuse macrophotography with microphotography, the bug-eye branch. Although microphotography is a sub-category and falls under the general umbrella of macrophotography it is a separate discipline with different rules.</td>', 'Originally posted by kiwinick: good idea although I believe it is not a true macro rather a close up   It rather depends on which definition of macro you go by, kiwinick: an image that is 1 to 1 (or larger) on recording media, or; an image that is 1 to 1 (or lager) on output media. With sensor sizes, and to a certain extent film sizes, varying so much it is hard to apply the first criteria with any form of consistent accuracy. Applying the second might be easier if the print output is used as a constant but with output media now meaning anything from a phone to a PC, this too is becoming hard to verify; though I believe my image conforms to it. Put the picture up on your screen or print it out and compare the size of an sd-card with the one in the image. Do not confuse macrophotography with microphotography, the bug-eye branch. Although microphotography is a sub-category and falls under the general umbrella of macrophotography it is a separate discipline with different rules.', '2014-06-06 04:34:30.000000', NULL, 0),
